\begin{enumerate}
\item 当 \(0\leq x<\frac{1}{2}\) 时，\(f(x)=f_{1}(x)\)，且 \(f_{1}'(x)=2-4x>0\)，同时 \(f_{1}(0)=\frac{1}{2}\)，\(\lim_{x\to(1/2)^{-}}f_{1}(x)=1\)，所以图象是抛物线 \(y=-2\left(x-\frac{1}{2}\right)^{2}+1\) 从实心点 \(\left(0,\frac{1}{2}\right)\) 出发的相应部分，单调上升并在 \(\left(\frac{1}{2},1\right)\) 处留下开端点. 当 \(\frac{1}{2}\leq x\leq1\) 时，\(f(x)=f_{2}(x)=-2x+2\)，图象是从实心点 \(\left(\frac{1}{2},1\right)\) 到实心点 \((1,0)\) 的线段. 因此图象由上述抛物线段和线段组成，在 \(\left(\frac{1}{2},1\right)\) 处取线段的实心点.

\item 由 \(y=-2x+2\)，得反函数 \(g(x)=1-\frac{x}{2}\)，其定义域为 \([0,1]\)，值域为 \([\frac{1}{2},1]\). 因为 \(a_{1}=1\in[0,1]\)，且 \(g\) 把 \([0,1]\) 映到 \([\frac{1}{2},1]\subset[0,1]\)，所以递推中的每一项都有定义. 数列满足 \(a_n=1-\frac{a_{n-1}}{2}\)，\((n\geq2)\)，且 \(a_1=1\). 设该递推的平衡值为 \(L\)，则 \(L=1-\frac{L}{2}\)，所以 \(L=\frac{2}{3}\). 因而 \(a_n-L=-\frac{1}{2}(a_{n-1}-L)\)，从而 \(a_n-\frac{2}{3}=\left(-\frac{1}{2}\right)^{n-1}\left(1-\frac{2}{3}\right)\). 所以 \(a_n=\frac{2}{3}+\frac{1}{3}\left(-\frac{1}{2}\right)^{n-1}\)，并且 \(\displaystyle\lim_{n\to\infty}a_n=\frac{2}{3}\).

\item 因为 \(x_0\in\left[0,\frac{1}{2}\right)\)，所以 \(x_1=f(x_0)=f_1(x_0)\in\left[\frac{1}{2},1\right)\)，从而 \(f(x_1)=f_2(x_1)\). 代入得 \(x_0=-2\left[-2\left(x_0-\frac{1}{2}\right)^2+1\right]+2=4\left(x_0-\frac{1}{2}\right)^2\).
于是 \(4x_0^2-5x_0+1=0\)，即 \((4x_0-1)(x_0-1)=0\). 结合 \(x_0\in[0,\frac{1}{2})\)，得到 \(x_0=\frac{1}{4}\). 代回可得 \(x_1=\frac{7}{8}\)，且 \(f(x_1)=\frac{1}{4}\)，满足条件.
\end{enumerate}

